import java.util.Comparator;
import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Set;
import java.util.TreeSet;

public class CourseRankerDemo {

    public enum Standing { FRESHMAN, SOPHOMORE, JUNIOR, SENIOR }

    public static class Student {
        final String id;
        final String name;
        final double gpa;
        final int credits;
        final Standing standing;
        final Set<String> completedCourses = new HashSet<>();

        public Student(String id, String name, double gpa, int credits, Standing standing) {
            this.id = id;
            this.name = name;
            this.gpa = gpa;
            this.credits = credits;
            this.standing = standing;
        }

        @Override
        public String toString() {
            return id + ":" + name + " (GPA:" + gpa + ", " + standing + ")";
        }
    }

    public static class WaitlistEntry {
        final Student student;
        final long timestamp;

        public WaitlistEntry(Student student, long timestamp) {
            this.student = student;
            this.timestamp = timestamp;
        }
    }

    public static class Course {
        final String code;
        final int capacity;
        final TreeSet<Student> enrolled;
        final PriorityQueue<WaitlistEntry> waitlist;

        public Course(String code, int capacity) {
            this.code = code;
            this.capacity = capacity;

            // Merit Comparator: GPA desc, Credits desc, ID asc
            Comparator<Student> meritOrder = Comparator
                .comparingDouble((Student s) -> s.gpa).reversed()
                .thenComparingInt((Student s) -> s.credits).reversed()
                .thenComparing(s -> s.id);
            this.enrolled = new TreeSet<>(meritOrder);

            // Waitlist Comparator: Standing priority desc, Timestamp asc
            Comparator<WaitlistEntry> waitlistOrder = Comparator
                .comparing((WaitlistEntry w) -> w.student.standing).reversed()
                .thenComparingLong(w -> w.timestamp);
            this.waitlist = new PriorityQueue<>(waitlistOrder);
        }

        public void enroll(Student student, long timestamp) {
            if (enrolled.size() < capacity) {
                enrolled.add(student);
                System.out.println("[ENROLLED] " + student.name);
            } else {
                waitlist.add(new WaitlistEntry(student, timestamp));
                System.out.println("[WAITLISTED] " + student.name);
            }
        }

        public void drop(Student student) {
            if (enrolled.remove(student)) {
                System.out.println("[DROPPED] " + student.name);
                if (!waitlist.isEmpty()) {
                    Student promoted = waitlist.poll().student;
                    enrolled.add(promoted);
                    System.out.println("[PROMOTED] " + promoted.name + " from waitlist!");
                }
            }
        }
    }

    public static void main(String[] args) {
        Course cs401 = new Course("CS401", 2);
        Student s1 = new Student("S1", "Alice", 3.9, 100, Standing.SENIOR);
        Student s2 = new Student("S2", "Bob", 3.5, 80, Standing.JUNIOR);
        Student s3 = new Student("S3", "Charlie", 3.8, 110, Standing.SENIOR);

        cs401.enroll(s1, 10);
        cs401.enroll(s2, 20);
        cs401.enroll(s3, 30); // Capacity full -> waitlist

        System.out.println("Enrolled: " + cs401.enrolled);

        // Alice drops -> Charlie should be promoted
        cs401.drop(s1);
        System.out.println("Enrolled after drop: " + cs401.enrolled);
    }
}
