public class PrerequisiteChecker {
    public static boolean hasPrerequisites(Set<String> completedCourses, Set<String> requiredPrerequisites) {
        if (requiredPrerequisites == null || requiredPrerequisites.isEmpty()) return true;
        if (completedCourses == null) return false;
        return completedCourses.containsAll(requiredPrerequisites);
    }
}

