import java.util.HashSet;
import java.util.Set;

public class CourseCapacityManager {
    private final int capacity;
    private final Set<String> enrolled = new HashSet<>();

    public CourseCapacityManager(int capacity) {
        this.capacity = capacity;
    }

    public boolean tryEnroll(String studentId) {
        if (studentId == null || enrolled.contains(studentId)) return false;
        if (enrolled.size() < capacity) {
            enrolled.add(studentId);
            return true;
        }
        return false;
    }

    public void drop(String studentId) {
        if (studentId != null) {
            enrolled.remove(studentId);
        }
    }
}

