import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

public class RankExtractor {
    public static class Student { public String id; public double gpa; }

    public static List<String> getTopKStudents(TreeSet<Student> enrolledStudents, int k) {
        if (enrolledStudents == null || k <= 0) return List.of();
        List<String> result = new ArrayList<>();
        int count = 0;
        for (Student s : enrolledStudents) {
            if (count++ >= k) break;
            result.add(s.id);
        }
        return List.copyOf(result);
    }
}
